<script language="javascript">
	var myCalendar;
	function doOnLoad() {
		myCalendar = new dhtmlXCalendarObject("calendar");
		myCalendar.hideTime();
		myCalendar.setDate("2025-08-16");
		myCalendar.attachEvent("onClick", function (){
			myCalendar.hide();
			window.location.href = "index.php?MDZAQEBA@" + myCalendar.getFormatedDate("%Y-%m-%d", myCalendar.getDate());
		});
		$("#topDate, .fa-calendar").click(function(){
			var calendarOffset = $("#calendar").offset();
			var dtOffset = $("#topDate").offset();			
			myCalendar.show();
			myCalendar.setPosition(calendarOffset.left-175, calendarOffset.top+15);
		});
		document.onclick = function(objEvent) {if (g_bIE) {g_objEvent = window.event;objTarget = g_objEvent.srcElement;mousebutton = g_objEvent.button;}else{g_objEvent = objEvent;objTarget = objEvent.target;mousebutton = objEvent.button;} if(objTarget.className != 'fa fa-calendar' && objTarget.id != 'topDate'){myCalendar.hide();}
		};
	};	
	
	$("#strSchKey").bind("keyup",function(e) {
		if (e.keyCode == 13) {onClickSearch();}
	});
	function checkChars(strValue) {
		if (!strValue || strValue.match(/[\\\/\^\*\'\"\(\)\[\]\|\$\-<>;,&%+=?]/))
			return false;
		else
			return true;
	}
	function onClickSearch() {
		if (!checkChars($("#strSchKey").val()))	{
			$("#strSchKey").css("background-color", "#ffe0e0");$("#strSchKey").focus();
			return false;
		} else {
			$("#strSchKey").css("background-color", "#fff");
		}
		onSearch("");
	}
	function onSearch() {
		jQuery.ajax({type:"POST", dataType:"html",
			url:"index.php?MDlA",
			data:"strSchKey=" + $("#strSchKey").val(),
			complete:function(jqXHR, status, responseText) {
				if (jqXHR.responseText.length > 0) {
					window.location = "index.php?" + jqXHR.responseText;
				} else {
					$("#strSchKey").val("");$("#strSchKey").css("background-color", "#ffe0e0");$("#strSchKey").focus();
				}
			}
		});
	}
	function his(v_strNewsID){
		jQuery.ajax({ 
		   type: "GET", 
		   url: "index.php?MDRA", 
		   data: "NewsID="+v_strNewsID, 
		   complete:function(jqXHR, status, responseText) {
		    		   } 
		});		
	};	
	function jsPaging(key, v_imid, ipage){
		jQuery.ajax({ 
		   type: "GET", 
		   url: "index.php?MDNA", 
		   data: "key="+key+"&imid="+v_imid+"&ipage="+ipage, 
		   complete:function(jqXHR, status, responseText) {		   	
		   	switch(key){
		   		case 1: $("#revoList, .col-sm-4").html(jqXHR.responseText); break;
		   		case 2: var arr = jqXHR.responseText.split("@");
		   			$("#leftp").html(arr[0]); $("#rightl").html(arr[1]);break;
		   	}		   	
		   } 
		});
	};
	$(window).scroll(function(){
		if ($(document).scrollTop() > 50) {
	      $(".scroll-to-top").css("display", "black").fadeIn("slow");
	    } else {
	      $(".scroll-to-top").css("display", "black").fadeOut("slow");
	    }
    });	
    $(document).ready(function() {
		$(".revoPhotoBG img").hover(function () { setScu(1); }, function () { setScu(0); });
		$(".revo_img img").hover(function () { setScu(1); }, function () { setScu(0); });
		$(".fancybox-media").attr("rel", "media-gallery").fancybox({
			openEffect:"none", mcloseEffect:"none", prevEffect:"none", nextEffect:"none",
			type:"iframe", arrows:false,
			helpers:{media:{}, buttons:{}}
		});	
	});
	function setScu(key){
		if(key == 1){ document.body.oncontextmenu = function(objEvent) { return false; }; document.body.oncontrolselect = function(objEvent) { return false; }; document.body.ondragstart = function(objEvent) { return false; }; document.body.onselectstart = function(objEvent) { return false; };
		}else{ document.body.oncontextmenu = function(objEvent) { return true; }; document.body.oncontrolselect = function(objEvent) { return true; }; document.body.ondragstart = function(objEvent) { return true; };document.body.onselectstart = function(objEvent) { return true; };
		}
	};
	var bctrlKey = 0;
	$(function(){ $('*:not(body)').on('mousewheel',function(e){if(bctrlKey == 1){e.preventDefault(); e.stopPropagation();}
		});});
	document.addEventListener('keyup', (event) => {
		var keyName = event.key;
		if (keyName === 'Control') {bctrlKey = 0;}
	}, false);
	document.addEventListener('keydown', (event) => {
		var keyName = event.key;
		if (keyName === 'Control') {bctrlKey = 1;}
		if (event.ctrlKey == true && event.keyCode == 70) {bctrlKey = 0;}
		if(event.keyCode == 123 || (event.ctrlKey == true && (event.keyCode == 107 || event.keyCode == 109)) || (event.ctrlKey == true && event.shiftKey && event.keyCode == 73)){event.preventDefault();}
	}, false);
