		  	    oPhoHNum = Math.floor(conWNum * ratio);
		  	};	   
			topY = Math.floor(( conHNum - oPhoHNum ) / 2 )-2;
			leftX = Math.floor(( conWNum - oPhoWNum ) / 2 );	
		    $(objImg[i]).css({"position":"relative", "width":oPhoWNum, "height":oPhoHNum, "top": (topY < 0)?0:topY});
		}  
